INSERT INTO _migration_440_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_albio_immunity_s1_001', 'topic_alevel_bio_immunity', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'Which cells synthesise and secrete antibodies?', 'multiple_choice', NULL, '["A. T-killer cells","B. Macrophages","C. Neutrophils","D. Plasma cells (activated B-lymphocytes)"]', 'D', 'When a B-lymphocyte whose surface antibody matches an antigen is activated (with help from T-helper cells), it divides by mitosis and differentiates into plasma cells, which mass-produce and secrete that antibody. Macrophages and neutrophils are phagocytes, and T-killer cells destroy infected cells. Therefore the correct answer is D: Plasma cells (activated B-lymphocytes).', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_albio_immunity_s1_002', 'topic_alevel_bio_immunity', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'Which statement best defines an antigen?', 'multiple_choice', NULL, '["A. A molecule, usually on the surface of a pathogen, that triggers a specific immune response","B. An antibody produced by plasma cells","C. A drug that kills bacteria","D. A type of white blood cell"]', 'A', 'Antigens are molecules — typically proteins or polysaccharides on the surface of pathogens — that are recognised as non-self by receptors on lymphocytes, triggering antibody production or a cell-mediated response directed specifically against them. Therefore the correct answer is A: A molecule, usually on the surface of a pathogen, that triggers a specific immune response.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_albio_immunity_s1_003', 'topic_alevel_bio_immunity', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'A person is injected with a harmless form of a pathogen''s antigens and later makes their own antibodies and memory cells. What type of immunity is this?', 'multiple_choice', NULL, '["A. Artificial passive immunity","B. Artificial active immunity","C. Natural passive immunity","D. Natural active immunity"]', 'B', 'The antigens were deliberately introduced by vaccination (artificial), and the person’s own immune system responded by producing antibodies and memory cells (active). Passive immunity instead delivers ready-made antibodies, as in an antiserum injection or transfer across the placenta. Therefore the correct answer is B: Artificial active immunity.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_albio_immunity_s1_004', 'topic_alevel_bio_immunity', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'Which lymphocyte directly destroys body cells infected with a virus?', 'multiple_choice', NULL, '["A. T-helper cell","B. B-memory cell","C. T-killer (cytotoxic T) cell","D. Plasma cell"]', 'C', 'Cytotoxic (T-killer) cells recognise viral antigens presented on the surface of infected cells and release substances such as perforin that kill those cells. T-helper cells coordinate the response by secreting cytokines, and plasma cells secrete antibodies into the blood. Therefore the correct answer is C: T-killer (cytotoxic T) cell.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_albio_immunity_s1_005', 'topic_alevel_bio_immunity', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'Why must new influenza vaccines be developed on a regular basis?', 'multiple_choice', NULL, '["A. Influenza viruses stop expressing antigens after each season","B. Vaccines lose all of their activity within a few months in the body","C. Memory cells permanently destroy the viral antigens","D. Antigenic variability — mutation changes the virus''s surface antigens, so existing memory cells and antibodies no longer match"]', 'D', 'Influenza has an RNA genome that mutates readily (antigenic drift, and occasionally antigenic shift), altering its haemagglutinin and neuraminidase surface antigens. Memory cells from an earlier vaccination then fail to recognise the new variants, so vaccines are reformulated each season to match circulating strains. Therefore the correct answer is D: Antigenic variability — mutation changes the virus''s surface antigens, so existing memory cells and antibodies no longer match.', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO3', NULL, NULL, 'board_cambridge'),
('q_albio_immunity_s1_006', 'topic_alevel_bio_immunity', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'A student compares the different ways in which the body is protected against infectious disease.', 'structured', NULL, NULL, '(a) In active immunity the person''s own lymphocytes respond to an antigen and produce antibodies and memory cells, giving long-lasting protection; in passive immunity ready-made antibodies are received, for example across the placenta or in an antiserum, giving immediate but short-lived protection without memory cells. (b) Memory B- and T-lymphocytes persist after a first infection; on re-exposure to the same antigen they clone rapidly and differentiate into plasma cells and effector T cells, so the antibody concentration rises faster and to a higher level than in the primary response. (c) Antibiotics target structures or processes unique to bacteria, such as peptidoglycan cell wall synthesis or 70S ribosomes; viruses lack these targets and replicate inside host cells using the host’s machinery, so antibiotics cannot act on them.', '(a) In active immunity the person''s own lymphocytes respond to an antigen and produce antibodies and memory cells, giving long-lasting protection; in passive immunity ready-made antibodies are received, for example across the placenta or in an antiserum, giving immediate but short-lived protection without memory cells. (b) Memory B- and T-lymphocytes persist after a first infection; on re-exposure to the same antigen they clone rapidly and differentiate into plasma cells and effector T cells, so the antibody concentration rises faster and to a higher level than in the primary response. (c) Antibiotics target structures or processes unique to bacteria, such as peptidoglycan cell wall synthesis or 70S ribosomes; viruses lack these targets and replicate inside host cells using the host’s machinery, so antibiotics cannot act on them.', 'medium', '6', '6', NULL, NULL, NULL, '1', NULL, NULL, 'Describe', 'AO2', NULL, NULL, 'board_cambridge');
INSERT INTO _migration_440_expected_parts (id, question_id, part_label, part_text, marks, correct_answer, display_order) VALUES ('sqp_q_albio_immunity_s1_006_a', 'q_albio_immunity_s1_006', 'a', 'Distinguish between active and passive immunity.', '2', 'In active immunity the person''s own lymphocytes respond to an antigen and produce antibodies and memory cells, giving long-lasting protection; in passive immunity ready-made antibodies are received, for example across the placenta or in an antiserum, giving immediate but short-lived protection without memory cells.', '1'),
('sqp_q_albio_immunity_s1_006_b', 'q_albio_immunity_s1_006', 'b', 'Describe the role of memory cells in the secondary immune response.', '2', 'Memory B- and T-lymphocytes persist after a first infection; on re-exposure to the same antigen they clone rapidly and differentiate into plasma cells and effector T cells, so the antibody concentration rises faster and to a higher level than in the primary response.', '2'),
('sqp_q_albio_immunity_s1_006_c', 'q_albio_immunity_s1_006', 'c', 'Explain why antibiotics are ineffective against viral diseases.', '2', 'Antibiotics target structures or processes unique to bacteria, such as peptidoglycan cell wall synthesis or 70S ribosomes; viruses lack these targets and replicate inside host cells using the host’s machinery, so antibiotics cannot act on them.', '3');
INSERT INTO _migration_440_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_440_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_440_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'alevel-bio-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM _migration_440_expected_parts p JOIN structured_question_parts sp ON sp.id = p.id WHERE NOT (sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_440_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) SELECT p.id, p.question_id, p.part_label, p.part_text, p.marks, p.correct_answer, NULL, 'text', p.display_order FROM _migration_440_expected_parts p WHERE NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = p.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'alevel-bio-sprint1-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.', 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/', 0, 1 FROM _migration_440_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_440_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_440_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 6 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_440_expected e ON e.id = r.question_id WHERE r.batch_id IS 'alevel-bio-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 6 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_440_expected e ON e.id = q.id) = 6 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_440_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 3 THEN 1 ELSE 0 END;
